def _write_partitioned(
    output: Path, table: str, columns: list[str], rows: list[dict[str, object]]
) -> None:
    by_period: dict[int, list[dict[str, object]]] = {}
    for row in rows:
        by_period.setdefault(int(row["FechaDatos"]), []).append(row)

    for period, period_rows in sorted(by_period.items()):
        path = output / table / f"FechaDatos={period}"
        path.mkdir(parents=True, exist_ok=True)
        pd.DataFrame(period_rows, columns=columns).to_parquet(
            path / "part-0.parquet", index=False
        )


def build_fixture(output: Path = DEFAULT_OUTPUT) -> None:
    output = output.resolve()
    if output == REAL_SILVER.resolve():
        raise ValueError("Refusing to overwrite real Silver data")

    if output.exists():
        shutil.rmtree(output)
    output.mkdir(parents=True)

    _write_partitioned(output, "fund_nav_daily", NAV_COLUMNS, NAV_ROWS)
    _write_partitioned(output, "fund_metadata", METADATA_COLUMNS, METADATA_ROWS)
    _write_partitioned(output, "fund_quarterly", QUARTERLY_COLUMNS, QUARTERLY_ROWS)
    _write_partitioned(output, "fund_holdings", HOLDINGS_COLUMNS, HOLDINGS_ROWS)
    _write_partitioned(
        output, "fund_period_financials", FINANCIALS_COLUMNS, FINANCIALS_ROWS
    )

    estr_path = output / "estr_daily"
    estr_path.mkdir(parents=True, exist_ok=True)
    pd.DataFrame(ESTR_ROWS, columns=ESTR_COLUMNS).to_parquet(
        estr_path / "part-0.parquet", index=False
    )


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Build a small deterministic Silver fixture for CI."
    )
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    build_fixture(args.output)
    print(f"Silver fixture written to {args.output}")


if __name__ == "__main__":
    main()
